import{_ as a,o as i,c as l,ae as o}from"./chunks/framework.Czhw_PXq.js";const p=JSON.parse('{"title":"架构与简介","description":"","frontmatter":{},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md"}'),r={name:"reference/architecture.md"};function c(t,e,d,s,n,h){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="架构与简介" tabindex="-1">架构与简介 <a class="header-anchor" href="#架构与简介" aria-label="Permalink to &quot;架构与简介&quot;">​</a></h1><p>本章节概述 Z-Drive 的整体架构、技术栈与主要模块。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li>后端：FastAPI（Python）</li><li>数据库：SQLite（可替换为 Postgres 等）</li><li>前端：React + Vite + Tailwind</li><li>定时任务：schedule + asyncio 循环</li><li>文档：VitePress</li></ul><h2 id="模块划分" tabindex="-1">模块划分 <a class="header-anchor" href="#模块划分" aria-label="Permalink to &quot;模块划分&quot;">​</a></h2><ul><li><code>app/</code>：后端应用代码（路由、服务、模型、配置等）</li><li><code>web/</code>：前端源码（React）</li><li><code>docs/</code>：VitePress 文档站</li><li><code>storage/</code>：运行时文件存储（gallery / cloud / snippets）</li></ul><h2 id="运行流程-简述" tabindex="-1">运行流程（简述） <a class="header-anchor" href="#运行流程-简述" aria-label="Permalink to &quot;运行流程（简述）&quot;">​</a></h2><ol><li>前端将文件上传到后端 API，管理接口统一挂载在 <code>/api</code> 前缀下。</li><li>后端存储原始文件并生成预览，图库图片会同步生成 WebP 预览，云盘会按需提供文件预览，代码片正文则写入本地文件存储。</li><li>元数据入库，支持短链、分享、访问统计与管理端鉴权。</li><li>定时任务每分钟执行一次，负责补齐图库预览、清理过期分享并维护同步任务。</li><li>前端通过管理接口或公共入口 <code>/f/{share_code}</code>、<code>/i/{file_key}</code>、<code>/p/{share_code}</code> 访问资源。</li></ol><h2 id="鉴权模型" tabindex="-1">鉴权模型 <a class="header-anchor" href="#鉴权模型" aria-label="Permalink to &quot;鉴权模型&quot;">​</a></h2><ul><li>管理端支持 JWT 登录态。</li><li>同时支持静态 <code>ADMIN_TOKEN</code>，便于自动化或外部系统接入。</li><li>如果 <code>ADMIN_TOKEN</code> 为空，则静态令牌通道会自动关闭。</li></ul><h2 id="目录约定" tabindex="-1">目录约定 <a class="header-anchor" href="#目录约定" aria-label="Permalink to &quot;目录约定&quot;">​</a></h2><ul><li><code>storage/gallery/original/</code>：图库原始文件。</li><li><code>storage/gallery/preview/</code>：图库预览图。</li><li><code>storage/cloud/</code>：云盘文件。</li><li><code>storage/cloud/.uploads/</code>：分片上传临时文件与任务元数据。</li><li><code>storage/snippets/</code>：代码片正文文件。</li><li>旧的 <code>storage/original/</code> 与 <code>storage/preview/</code> 仍保留兼容读取逻辑，便于历史数据平滑迁移。</li></ul><p>更多细节见下游各章节（后端、接口、配置）。</p>',13)])])}const _=a(r,[["render",c]]);export{p as __pageData,_ as default};
